// --------------------------------------------------------------------------------------------------------------------
// What STRONG.EXE grab makes of each source file, as measured by running it (reversing/notes/about_grab.md).
//
// grab_manifest.tsv is generated by reversing/scripts/ungrab_check.py from a trace of the original packer under the
// emulator, and that script fails if the embedded copy and a fresh trace disagree. One row per STRONG.DAT entry
// says which file made it and how; anim rows carry 3000:3580's descriptors for the 0xfe marker layout.

use crate::error::{FormatError, Result};

/// The manifest as traced, embedded so the ungrab needs nothing but STRONG.DAT.
const EMBEDDED: &str = include_str!("grab_manifest.tsv");

/// What the packer did to a loaded picture before cutting from it, in order.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum Edit {
    /// 2000:0292: every pixel of one colour becomes another.
    Recolour { from: u8, to: u8 },
    /// 3000:bc00: pixels 0x50-0x7f up by 0x50, 0x80-0xcf down by 0x30, the palette moved with them.
    Rotate,
}

/// Where a picture was loaded and what was done to it before use.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Load {
    /// The sheet column that lands at frame column 0; non-zero for viewports into a wide sheet.
    pub x: usize,
    pub edits: Vec<Edit>,
}

/// An inclusive rectangle in frame coordinates, as 2000:3dd0 takes it.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct Rect {
    pub x0: usize,
    pub y0: usize,
    pub x1: usize,
    pub y1: usize,
}

impl Rect {
    pub fn width(&self) -> usize {
        self.x1 - self.x0 + 1
    }

    pub fn height(&self) -> usize {
        self.y1 - self.y0 + 1
    }
}

/// How the packer made one entry.
#[derive(Clone, PartialEq, Eq, Debug)]
pub enum Op {
    /// A rectangle cut out of a picture: kind 1 plain, 2 with an anchor, 4 an animation frame.
    Cut { file: String, kind: u8, rect: Rect, load: Load },
    /// Palette bytes stashed from offset at of the loaded (and edited) palette.
    Palette { file: String, at: usize, size: usize, edits: Vec<Edit> },
    /// The font record 2000:2a25 parses out of a delimited sheet.
    Font { file: String },
    /// Single pixels read at these frame offsets (6000:e846 into ds:89a1).
    Samples { file: String, load: Load, offsets: Vec<usize> },
    /// A kind 3 audio record, 3000:c79c: an .xmi copied whole, anything else read as a VOC.
    Sound { file: String },
    /// A whole file, with 15 zero bytes after it when pad is set (3000:cbd0).
    Copy { file: String, pad: bool },
}

impl Op {
    /// The DOS name of the file the entry came from, case folded.
    pub fn file(&self) -> &str {
        match self {
            Op::Cut { file, .. } | Op::Palette { file, .. } | Op::Font { file } | Op::Samples { file, .. } | Op::Sound { file } | Op::Copy { file, .. } => file,
        }
    }

    /// A short word for the operation, as the map and the messages name it.
    pub fn how(&self) -> &'static str {
        match self {
            Op::Cut { kind: 1, .. } => "cut",
            Op::Cut { kind: 2, .. } => "cut+anchor",
            Op::Cut { .. } => "frame",
            Op::Palette { .. } => "palette",
            Op::Font { .. } => "font",
            Op::Samples { .. } => "pixels",
            Op::Sound { .. } => "audio",
            Op::Copy { pad: true, .. } => "copy+15",
            Op::Copy { .. } => "copy",
        }
    }
}

/// One of 3000:3580's 30-byte descriptors, the fields the marker layout needs.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct Descriptor {
    /// The word at +1: the column the marker scan starts from.
    pub x00: usize,
    /// The byte at +9: how far a new column of frames moves the marker.
    pub xstep: usize,
    /// The byte at +0x1b: how many frames this descriptor cuts.
    pub frames: usize,
    /// Bit 0 of +0x1c: the frames' advances are measured from 0xfe markers.
    pub marked: bool,
}

/// One animation sheet: its file, where it was loaded, its descriptors in order.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct AnimSheet {
    pub file: String,
    pub load_x: usize,
    pub descriptors: Vec<Descriptor>,
}

/// The whole manifest: the container it was traced against and one Op per entry.
#[derive(Clone)]
pub struct Manifest {
    pub dat_md5: String,
    pub dat_size: usize,
    pub exe_md5: String,
    /// Indexed by ordinal; every entry the container holds.
    pub ops: Vec<Op>,
    /// In the order of each sheet's first frame.
    pub anims: Vec<AnimSheet>,
}

impl std::fmt::Debug for Manifest {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Manifest {} entries, {} animation sheets, for STRONG.DAT {}", self.ops.len(), self.anims.len(), self.dat_md5)
    }
}

// --------------------------------------------------------------------------------------------------------------------
// Parsing

impl Manifest {
    /// The manifest compiled into this crate.
    pub fn embedded() -> Result<Manifest> {
        Manifest::parse(EMBEDDED)
    }

    /// Parse and cross-check a manifest; any row it cannot account for is an error.
    pub fn parse(text: &str) -> Result<Manifest> {
        let mut dat: Option<(String, usize, usize)> = None;
        let mut exe_md5: Option<String> = None;
        let mut ops: Vec<Op> = Vec::new();
        let mut anims: Vec<AnimSheet> = Vec::new();
        for (k, line) in text.lines().enumerate() {
            let line_no = k + 1;
            if line.starts_with('#') || line.trim().is_empty() {
                continue;
            }
            let bad = |why: &str| FormatError::Ungrab(format!("manifest line {line_no}: {why}"));
            let cols: Vec<&str> = line.split('\t').collect();
            let want = |n: usize| if cols.len() == n { Ok(()) } else { Err(bad(&format!("{} columns, wanted {n}", cols.len()))) };
            let num = |at: usize| cols[at].parse::<usize>().map_err(|_| bad(&format!("column {} ({:?}) is not a number", at + 1, cols[at])));
            match cols[0] {
                "dat" => {
                    want(4)?;
                    dat = Some((cols[1].to_string(), num(2)?, num(3)?));
                }
                "exe" => {
                    want(2)?;
                    exe_md5 = Some(cols[1].to_string());
                }
                "anim" => {
                    want(4)?;
                    let descriptors = cols[3].split(',').map(|d| parse_descriptor(d).ok_or_else(|| bad(&format!("descriptor {d:?} is not x00:xstep:frames:marked")))).collect::<Result<Vec<_>>>()?;
                    anims.push(AnimSheet { file: cols[1].to_string(), load_x: num(2)?, descriptors });
                }
                tag => {
                    if cols.len() < 3 {
                        return Err(bad("too few columns"));
                    }
                    if num(1)? != ops.len() {
                        return Err(bad(&format!("entry {} where {} was next", cols[1], ops.len())));
                    }
                    let file = cols[2].to_string();
                    let edits = |at: usize| parse_edits(cols[at]).ok_or_else(|| bad(&format!("edits {:?} are not a>b, rot or -", cols[at])));
                    let op = match tag {
                        "cut" => {
                            want(10)?;
                            let rect = Rect { x0: num(4)?, y0: num(5)?, x1: num(6)?, y1: num(7)? };
                            let kind = num(3)?;
                            if ![1, 2, 4].contains(&kind) || rect.x1 < rect.x0 || rect.y1 < rect.y0 {
                                return Err(bad("not a kind 1, 2 or 4 cut of a proper rectangle"));
                            }
                            Op::Cut { file, kind: kind as u8, rect, load: Load { x: num(8)?, edits: edits(9)? } }
                        }
                        "pal" => {
                            want(6)?;
                            Op::Palette { file, at: num(3)?, size: num(4)?, edits: edits(5)? }
                        }
                        "font" => {
                            want(3)?;
                            Op::Font { file }
                        }
                        "samp" => {
                            want(6)?;
                            let offsets = cols[5].split(',').map(|o| o.parse::<usize>().map_err(|_| bad(&format!("offset {o:?}")))).collect::<Result<Vec<_>>>()?;
                            Op::Samples { file, load: Load { x: num(3)?, edits: edits(4)? }, offsets }
                        }
                        "snd" => {
                            want(3)?;
                            Op::Sound { file }
                        }
                        "copy" => {
                            want(4)?;
                            Op::Copy { file, pad: num(3)? == 1 }
                        }
                        other => return Err(bad(&format!("unknown row type {other:?}"))),
                    };
                    ops.push(op);
                }
            }
        }
        let (dat_md5, dat_size, count) = dat.ok_or_else(|| FormatError::Ungrab("manifest has no dat row".into()))?;
        let exe_md5 = exe_md5.ok_or_else(|| FormatError::Ungrab("manifest has no exe row".into()))?;
        if ops.len() != count {
            return Err(FormatError::Ungrab(format!("manifest says {count} entries and has {}", ops.len())));
        }
        let manifest = Manifest { dat_md5, dat_size, exe_md5, ops, anims };
        manifest.check_anims()?;
        Ok(manifest)
    }

    /// Every animation sheet's descriptors cover exactly the frames cut from its file, and every frame has a sheet.
    fn check_anims(&self) -> Result<()> {
        for anim in &self.anims {
            let want: usize = anim.descriptors.iter().map(|d| d.frames).sum();
            let got = self.frames_of(&anim.file).len();
            if want != got {
                return Err(FormatError::Ungrab(format!("manifest: {} has descriptors for {want} frames and {got} frame cuts", anim.file)));
            }
        }
        for op in &self.ops {
            if let Op::Cut { kind: 4, file, .. } = op {
                if !self.anims.iter().any(|a| &a.file == file) {
                    return Err(FormatError::Ungrab(format!("manifest: a frame of {file}, which has no animation sheet")));
                }
            }
        }
        Ok(())
    }

    /// The ordinals of every frame cut from one file, in order.
    pub fn frames_of(&self, file: &str) -> Vec<usize> {
        self.ops.iter().enumerate().filter(|(_, op)| matches!(op, Op::Cut { kind: 4, file: f, .. } if f == file)).map(|(n, _)| n).collect()
    }

    /// Every distinct source file the entries name, in the order of the first entry each makes.
    pub fn files(&self) -> Vec<&str> {
        let mut seen = std::collections::HashSet::new();
        self.ops.iter().map(|op| op.file()).filter(|f| seen.insert(*f)).collect()
    }
}

fn parse_descriptor(text: &str) -> Option<Descriptor> {
    let parts: Vec<usize> = text.split(':').map(|p| p.parse().ok()).collect::<Option<Vec<_>>>()?;
    match parts[..] {
        [x00, xstep, frames, marked] if marked <= 1 && frames > 0 => Some(Descriptor { x00, xstep, frames, marked: marked == 1 }),
        _ => None,
    }
}

fn parse_edits(text: &str) -> Option<Vec<Edit>> {
    if text == "-" {
        return Some(Vec::new());
    }
    text.split(',')
        .map(|e| {
            if e == "rot" {
                return Some(Edit::Rotate);
            }
            let (from, to) = e.split_once('>')?;
            Some(Edit::Recolour { from: from.parse().ok()?, to: to.parse().ok()? })
        })
        .collect()
}

