// --------------------------------------------------------------------------------------------------------------------
// Tests

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_embedded_manifest_is_the_census_about_grab_md_gives() {
        let m = Manifest::embedded().expect("parses");
        assert_eq!((m.ops.len(), m.dat_size, m.dat_md5.as_str()), (3451, 5259205, "96557d434c8960699a125b0fc5e2f96b"));
        assert_eq!(m.exe_md5, "81d23814efc42db5674352469697d654");
        let count = |how: &str| m.ops.iter().filter(|op| op.how() == how).count();
        assert_eq!((count("cut"), count("cut+anchor"), count("frame")), (134, 868, 2190));
        assert_eq!((count("palette"), count("font"), count("pixels"), count("audio")), (65, 1, 1, 138));
        assert_eq!((count("copy"), count("copy+15")), (38, 16));
        assert_eq!(m.files().len(), 475, "475 distinct files are opened");
        assert_eq!(m.files().iter().filter(|f| f.ends_with(".lbm")).count(), 291);
        assert_eq!(m.anims.len(), 79, "79 descriptor tables");
        assert_eq!(m.ops[731].file(), "triangls.lbm");
        assert_eq!(m.ops[3438], Op::Copy { file: "sky06.fli".into(), pad: false });
    }

    #[test]
    fn rows_are_parsed_and_bad_ones_refused() {
        let good = "dat\tabc\t10\t2\nexe\tdef\nanim\ta.lbm\t0\t8:0:1:1\ncut\t0\ta.lbm\t4\t1\t2\t3\t4\t0\t255>0,rot\nsnd\t1\tz.voc\n";
        let m = Manifest::parse(good).expect("parses");
        assert_eq!(m.ops[0], Op::Cut { file: "a.lbm".into(), kind: 4, rect: Rect { x0: 1, y0: 2, x1: 3, y1: 4 }, load: Load { x: 0, edits: vec![Edit::Recolour { from: 255, to: 0 }, Edit::Rotate] } });
        assert_eq!(m.anims[0].descriptors[0], Descriptor { x00: 8, xstep: 0, frames: 1, marked: true });
        assert!(Manifest::parse(&good.replace("snd\t1", "snd\t2")).is_err(), "ordinals out of order");
        assert!(Manifest::parse(&good.replace("\t2\nexe", "\t3\nexe")).is_err(), "count disagrees");
        assert!(Manifest::parse(&good.replace("8:0:1:1", "8:0:2:1")).is_err(), "descriptors cover a missing frame");
        assert!(Manifest::parse(&good.replace("255>0", "255=0")).is_err(), "edits");
        assert!(Manifest::parse(&good.replace("snd", "hum")).is_err(), "unknown row");
    }
}
